   206  void vcardparameter_set_value_from_string(vcardparameter *param,
   207                                            const char *val)
   208  {
   209      icalerror_check_arg_rv((param != 0), "param");
   210      icalerror_check_arg_rv((val != 0), "val");
   211
   212      if (param->value_kind == VCARD_INTEGER_VALUE) {
   213          param->data = atoi(val);
   214
   215      } else if (param->value_kind == VCARD_DATEANDORTIME_VALUE) {
   216          ((struct vcardparameter_impl *)param)->date = vcardtime_from_string(val, 0);
   217
   218      } else if (param->value_kind == VCARD_TEXT_VALUE) {
   219          ((struct vcardparameter_impl *)param)->string = icalmemory_strdup(val);
   220
   221      } else if (param->value_kind == VCARD_STRUCTURED_VALUE) {
   222          ((struct vcardparameter_impl *)param)->structured =
   223              vcardstructured_new_from_string(val);
   224
   225      } else {
   226          /* Search through the parameter map to find a matching kind */
   227          int enumeration = _vcardparameter_string_to_enum(val, param->kind);
   228
   229          if (enumeration != 0) {
   230              param->data = enumeration;
   231
   232          } else {
   233              /* The kind was in the parameter map, but the string did not
   234                 match, so assume that it is an alternate value, like an
   235                 X-value. */
   236
   237              vcardparameter_set_xvalue(param, val);
   238          }
   239      }
   240  }
